// LZ4 blocks made by python-lz4 (the reference liblz4): empty, one byte, a
// repeated phrase, a 1 KiB pattern, a long run (overlapping match), 3000
// random bytes (incompressible: long literals with length extension), and a
// journal-like payload.
var lz4Vectors = []struct{ raw, block string }{
	{"", "00"},
	{"61", "1061"},
	{"68656c6c6f2068656c6c6f2068656c6c6f2068656c6c6f2068656c6c6f2068656c6c6f", "6f68656c6c6f200600055068656c6c6f"},
	{"",
		""},
	{"",
		"1f580100ffffffd750207461696c"},
	{"",
		""},
	{"",
		"ff014d4553534147453d61626364656667680800ffffffffffffffffff49506465666768"},
}

func TestLZ4Vectors(t *testing.T) {
	for i, v := range lz4Vectors {
		raw, _ := hex.DecodeString(v.raw)
		block, _ := hex.DecodeString(v.block)
		got, err := lz4Block(block, len(raw))
		if err != nil || !bytes.Equal(got, raw) {
			t.Fatalf("vector %d: err %v, %d bytes", i, err, len(got))
		}
		// journald's framing: a little-endian 64-bit size, then the block.
		framed := binary.LittleEndian.AppendUint64(nil, uint64(len(raw)))
		if got, err := journalLZ4(append(framed, block...)); err != nil || !bytes.Equal(got, raw) {
			t.Fatalf("vector %d framed: %v", i, err)
		}
		// Truncated or mis-sized input fails cleanly.
		if len(block) > 1 {
			if _, err := lz4Block(block[:len(block)-1], len(raw)); err == nil {
				t.Errorf("vector %d: truncated block decoded", i)
			}
		}
		if _, err := lz4Block(block, len(raw)+1); err == nil {
			t.Errorf("vector %d: wrong size accepted", i)
		}
	}
}

// buildJournal assembles a small journal file: a 272-byte header, a DATA
// object per distinct payload and an ENTRY per entry. It exercises the
// reader's plumbing; the format itself is checked against journalctl on real
// journald-written files by TestJournalMatchesJournalctl.
func buildJournal(compact bool, entries [][]string) []byte {
	const hdr = 272
	f := make([]byte, hdr)
	copy(f, journalSignature)
	if compact {
		binary.LittleEndian.PutUint32(f[12:], journalIncompatCompact)
	}
	f[16] = 2 // archived
	binary.LittleEndian.PutUint64(f[88:], hdr)
	pad := func() {
		for len(f)%8 != 0 {
			f = append(f, 0)
		}
	}
	obj := func(typ byte, body []byte) uint64 {
		pad()
		at := uint64(len(f))
		h := make([]byte, journalObjHeader)
		h[0] = typ
		binary.LittleEndian.PutUint64(h[8:], uint64(journalObjHeader+len(body)))
		f = append(f, h...)
		f = append(f, body...)
		return at
	}
	data := map[string]uint64{}
	var tail uint64
	for i, fields := range entries {
		var offs []uint64
		for _, p := range fields {
			if _, ok := data[p]; !ok {
				body := make([]byte, 48) // hash, next_hash, next_field, entry, entry_array, n_entries
				if compact {
					body = append(body, make([]byte, 8)...)
				}
				data[p] = obj(journalObjData, append(body, p...))
			}
			offs = append(offs, data[p])
		}
		body := make([]byte, 48) // seqnum, realtime, monotonic, boot_id, xor_hash
		binary.LittleEndian.PutUint64(body[0:], uint64(i+1))
		binary.LittleEndian.PutUint64(body[8:], 1_700_000_000_000_000+uint64(i))
		binary.LittleEndian.PutUint64(body[16:], 1000+uint64(i))
		for _, o := range offs {
			if compact {
				body = binary.LittleEndian.AppendUint32(body, uint32(o))
			} else {
				body = binary.LittleEndian.AppendUint64(body, o)
				body = binary.LittleEndian.AppendUint64(body, 0)
			}
		}
		tail = obj(journalObjEntry, body)
	}
	binary.LittleEndian.PutUint64(f[96:], uint64(len(f))-hdr) // arena
	binary.LittleEndian.PutUint64(f[136:], tail)
	binary.LittleEndian.PutUint64(f[152:], uint64(len(entries)))
	return append(f, make([]byte, 4096)...) // preallocated space past the tail
}

func readAll(t *testing.T, data []byte) []*journalEntry {
	t.Helper()
	j, err := openJournal(data)
	if err != nil {
		t.Fatal(err)
	}
	var out []*journalEntry
	j.entries(func(e *journalEntry) bool { out = append(out, e); return true })
	return out
}

func TestJournalReaderLayouts(t *testing.T) {
	entries := [][]string{
		{"MESSAGE=Accepted publickey for deploy from 10.0.4.12", "SYSLOG_IDENTIFIER=sshd", "_PID=4103"},
		{"MESSAGE=filler", "SYSLOG_IDENTIFIER=sshd", "EQUALS=a=b=c"},
	}
	for _, compact := range []bool{false, true} {
		got := readAll(t, buildJournal(compact, entries))
		if len(got) != 2 {
			t.Fatalf("compact=%v: %d entries", compact, len(got))
		}
		if got[0].Get("SYSLOG_IDENTIFIER") != "sshd" || got[0].Get("_PID") != "4103" ||
			got[1].Get("EQUALS") != "a=b=c" || got[1].Seqnum != 2 || got[1].Monotonic != 1001 {
			t.Fatalf("compact=%v: %+v %+v", compact, got[0], got[1])
		}
	}
}

func TestJournalHostileInput(t *testing.T) {
	walk := func(b []byte) {
		if j, err := openJournal(b); err == nil {
			j.entries(func(*journalEntry) bool { return true })
		}
	}
	for _, compact := range []bool{true, false} {
		good := buildJournal(compact, [][]string{{"MESSAGE=a", "X=1"}, {"MESSAGE=b"}})
		for n := 0; n <= len(good); n += 3 {
			walk(good[:n])
		}
		x := uint32(2463534242)
		for i := 0; i < 20000; i++ {
			x ^= x << 13
			x ^= x >> 17
			x ^= x << 5
			b := append([]byte(nil), good...)
			b[int(x)%len(b)] = byte(x >> 8)
			b[int(x>>11)%len(b)] = 0xFF
			walk(b)
		}
	}
	if _, err := openJournal([]byte("not a journal")); err == nil {
		t.Error("garbage accepted")
	}

	// Offsets near 2^64 must not wrap past the bounds checks: an entry item
	// (regular layout: 64-bit) and the header's tail object size.
	reg := buildJournal(false, [][]string{{"MESSAGE=a"}})
	j, err := openJournal(reg)
	if err != nil {
		t.Fatal(err)
	}
	tail, _ := le64(reg, 136)
	item := tail + 16 + 48 // the entry's first item
	b := append([]byte(nil), reg...)
	binary.LittleEndian.PutUint64(b[item:], ^uint64(7))
	walk(b)
	b = append([]byte(nil), reg...)
	binary.LittleEndian.PutUint64(b[tail+8:], ^uint64(0)-tail+16) // tail+size wraps to 15
	if j2, err := openJournal(b); err != nil || j2.end != j.end {
		t.Errorf("a wrapping tail size moved the end of the file: %v", err)
	}
}

// TestJournalMatchesJournalctl checks the reader against journalctl, the
// reference implementation, on real journald-written files: every entry's
// sequence number and timestamps and every field value must agree, and each
// field journalctl shows that this reader can't decode must be one it
// counted as undecoded (zstd/XZ). Point LRNG_JOURNAL_SAMPLES at a directory
// of journal files; skipped when unset or without journalctl.
func TestJournalMatchesJournalctl(t *testing.T) {
	dir := os.Getenv("LRNG_JOURNAL_SAMPLES")
	jc, err := exec.LookPath("journalctl")
	if dir == "" || err != nil {
		t.Skip("set LRNG_JOURNAL_SAMPLES (and have journalctl) to run")
	}
	var files []string
	_ = filepath.WalkDir(dir, func(p string, d os.DirEntry, err error) error {
		if err == nil && !d.IsDir() && strings.Contains(d.Name(), ".journal") {
			files = append(files, p)
		}
		return nil
	})
	if len(files) == 0 {
		t.Fatalf("no journal files under %s", dir)
	}
	totalEntries, totalFields, totalUndecoded := 0, 0, 0
	for _, f := range files {
		data, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		ours := map[uint64]*journalEntry{}
		for _, e := range readAll(t, data) {
			ours[e.Seqnum] = e
		}
		out, err := exec.Command(jc, "--file", f, "-o", "json", "--all", "--no-pager").Output()
		if err != nil {
			t.Fatalf("%s: journalctl: %v", f, err)
		}
		n := 0
		for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
			var ref map[string]any
			if err := json.Unmarshal([]byte(line), &ref); err != nil {
				t.Fatalf("%s: %v", f, err)
			}
			n++
			seq, _ := strconv.ParseUint(ref["__SEQNUM"].(string), 10, 64)
			e := ours[seq]
			if e == nil {
				t.Fatalf("%s: entry %d missing", f, seq)
			}
			if rt, _ := strconv.ParseUint(ref["__REALTIME_TIMESTAMP"].(string), 10, 64); rt != e.Realtime {
				t.Fatalf("%s #%d: realtime %d, journalctl %d", f, seq, e.Realtime, rt)
			}
			if mt, _ := strconv.ParseUint(ref["__MONOTONIC_TIMESTAMP"].(string), 10, 64); mt != e.Monotonic {
				t.Fatalf("%s #%d: monotonic %d, journalctl %d", f, seq, e.Monotonic, mt)
			}
			mine := map[string][]string{}
			for _, fl := range e.Fields {
				if fl.ok {
					mine[fl.name] = append(mine[fl.name], fl.value)
				}
			}
			missing := 0
			for k, v := range ref {
				if strings.HasPrefix(k, "__") {
					continue
				}
				want := jsonValues(v)
				got, ok := mine[k]
				if !ok {
					missing += len(want)
					continue
				}
				sort.Strings(got)
				sort.Strings(want)
				if fmt.Sprint(got) != fmt.Sprint(want) {
					t.Fatalf("%s #%d %s: %q, journalctl %q", f, seq, k, got, want)
				}
				totalFields += len(got)
				delete(mine, k)
			}
			if len(mine) != 0 {
				t.Fatalf("%s #%d: fields journalctl doesn't show: %v", f, seq, mine)
			}
			if missing != e.Undecoded {
				t.Fatalf("%s #%d: %d field(s) not read, %d counted undecoded", f, seq, missing, e.Undecoded)
			}
			totalUndecoded += missing
		}
		if n != len(ours) {
			t.Fatalf("%s: %d entries, journalctl %d", f, len(ours), n)
		}
		totalEntries += n
		t.Logf("%s: %d entries agree", filepath.Base(filepath.Dir(f))+"/"+filepath.Base(f), n)
	}
	t.Logf("%d files, %d entries, %d field values identical to journalctl, %d undecoded (zstd/xz) as counted",
		len(files), totalEntries, totalFields, totalUndecoded)
}

// jsonValues normalises a journalctl JSON field: a string, a byte array
// (binary or invalid UTF-8), or an array of either (a repeated field).
func jsonValues(v any) []string {
	switch x := v.(type) {
	case string:
		return []string{x}
	case []any:
		if len(x) > 0 {
			if _, isNum := x[0].(float64); isNum {
				b := make([]byte, len(x))
				for i, n := range x {
					b[i] = byte(n.(float64))
				}
				return []string{string(b)}
			}
		}
		var out []string
		for _, e := range x {
			out = append(out, jsonValues(e)...)
		}
		return out
	}
	return []string{fmt.Sprint(v)}
}
